#include <vector>

class Solution {
public:
    int wateringPlants(std::vector<int>& plants, int capacity) {
        int steps = 0;
        int water = capacity;

        for (int i = 0; i < static_cast<int>(plants.size()); ++i) {
            if (water < plants[i]) {
                steps += 2 * i;
                water = capacity;
            }
            steps++;
            water -= plants[i];
        }
        return steps;
    }
};

class Solution {
    public int wateringPlants(int[] plants, int capacity) {
        int steps = 0;
        int water = capacity;

        for (int i = 0; i < plants.length; i++) {
            if (water < plants[i]) {
                steps += 2 * i;
                water = capacity;
            }
            steps++;
            water -= plants[i];
        }
        return steps;
    }
}

