var wateringPlants = function(plants, capacity) {
    let steps = 0;
    let water = capacity;

    for (let i = 0; i < plants.length; i++) {
        if (water < plants[i]) {
            steps += 2 * i;
            water = capacity;
        }
        steps++;
        water -= plants[i];
    }
    return steps;
};
